def asteroid_collision(asteroids):
    asteroids = list(asteroids)
    i = 0
    while i < len(asteroids) - 1:
        a, b = asteroids[i], asteroids[i + 1]
        if a > 0 and b < 0:                                                 # ONLY a right-mover immediately followed by a left-mover can collide
            if a < -b:
                del asteroids[i]                                           # the right-mover explodes
                i = max(i - 1, 0)                                          # step back: the newly adjacent pair might ALSO collide
            elif a == -b:
                del asteroids[i:i + 2]                                     # both explode
                i = max(i - 1, 0)
            else:
                del asteroids[i + 1]                                       # the left-mover explodes
                i = max(i - 1, 0)
        else:
            i += 1
    return asteroids


if __name__ == "__main__":
    print(asteroid_collision([10, 2, -5]))

