import java.util.*;

public class Main {
    List<Integer> asteroidCollision(List<Integer> asteroids) {
        List<Integer> result = new ArrayList<>(asteroids);
        int i = 0;
        while (i < result.size() - 1) {
            int a = result.get(i), b = result.get(i + 1);
            if (a > 0 && b < 0) {                                                   // ONLY a right-mover immediately followed by a left-mover can collide
                if (a < -b) {
                    result.remove(i);                                                  // the right-mover explodes
                    i = Math.max(i - 1, 0);                                            // step back: the newly adjacent pair might ALSO collide
                } else if (a == -b) {
                    result.remove(i + 1);
                    result.remove(i);                                                  // both explode
                    i = Math.max(i - 1, 0);
                } else {
                    result.remove(i + 1);                                              // the left-mover explodes
                    i = Math.max(i - 1, 0);
                }
            } else {
                i++;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> asteroids = new ArrayList<>(Arrays.asList(10, 2, -5));
        System.out.println(solution.asteroidCollision(asteroids));
    }
}

