import java.util.*;

public class Main {
    int[] asteroidCollision(int[] asteroids) {
        Deque<Integer> stack = new ArrayDeque<>();                                   // surviving asteroids so far, left to right
        for (int a : asteroids) {
            boolean alive = true;
            while (alive && a < 0 && !stack.isEmpty() && stack.peek() > 0) {            // only a LEFT-mover meeting a RIGHT-mover on top can collide
                int top = stack.peek();
                if (top < -a) {
                    stack.pop();                                                            // the right-mover (smaller) explodes; keep checking further down
                } else if (top == -a) {
                    stack.pop();                                                            // equal size: BOTH explode
                    alive = false;
                } else {
                    alive = false;                                                          // the right-mover (bigger) survives; this left-mover explodes
                }
            }
            if (alive) stack.push(a);
        }
        int[] result = new int[stack.size()];
        for (int i = result.length - 1; i >= 0; i--) result[i] = stack.pop();
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] asteroids = {10, 2, -5};
        int[] result = solution.asteroidCollision(asteroids);
        for (int v : result) System.out.print(v + " ");
        System.out.println();
    }
}

